const statusDeploys = `-- name: StatusDeploys :many
SELECT d.id, d.state, d.cause, d.commit_sha, d.status_sent, d.started_at, d.finished_at, s.name, s.repo, e.name AS env, p.name AS project
FROM deploys d JOIN services s ON s.id = d.service_id JOIN environments e ON e.id = s.environment_id JOIN projects p ON p.id = e.project_id
WHERE d.created_at > ? AND d.commit_sha != '' AND s.repo != '' ORDER BY d.created_at
`

type StatusDeploysRow struct {
	ID         string
	State      string
	Cause      string
	CommitSha  string
	StatusSent string
	StartedAt  sql.NullInt64
	FinishedAt sql.NullInt64
	Name       string
	Repo       string
	Env        string
	Project    string
}

func (q *Queries) StatusDeploys(ctx context.Context, createdAt int64) ([]StatusDeploysRow, error) {
	rows, err := q.db.QueryContext(ctx, statusDeploys, createdAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StatusDeploysRow
	for rows.Next() {
		var i StatusDeploysRow
		if err := rows.Scan(
			&i.ID,
			&i.State,
			&i.Cause,
			&i.CommitSha,
			&i.StatusSent,
			&i.StartedAt,
			&i.FinishedAt,
			&i.Name,
			&i.Repo,
			&i.Env,
			&i.Project,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

